cd /tmp && cat > /tmp/t.js <<'EOF'
const axios = require('/testbed');
const http = require('http');
const s = http.createServer((q, r) => setTimeout(() => r.end('x'), 500)).listen(4445, () => {
  axios.get('http://localhost:4445/', {timeout: 100, timeoutErrorMessage: 'Custom Timeout Error Message'})
    .catch(e => { console.log(e.message, e.code); s.close(); process.exit(0); });
});
EOF
node /tmp/t.js

